package retry

import (
	"context"
	"time"
)

const maxAttempts = 3

// Do runs f until it succeeds or the attempts run out.
func Do(ctx context.Context, f func() error) error {
	var err error
	for range maxAttempts {
		if err = f(); err == nil {
			return nil
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(100 * time.Millisecond):
		}
	}
	return err
}
